import { createHash } from 'node:crypto'
import { readdir, readFile } from 'node:fs/promises'
import { join } from 'node:path'

/** Hash generated bytes as well as provenance; retrieval timestamps are not data identity. */
export async function dataFingerprint(content, directory) {
  const files = []
  async function visit(relative) {
    const entries = await readdir(join(directory, relative), { withFileTypes: true })
    for (const entry of entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
      const path = `${relative}/${entry.name}`
      if (entry.isDirectory()) await visit(path)
      else {
        const bytes = await readFile(join(directory, path))
        files.push([path, createHash('sha256').update(bytes).digest('hex')])
      }
    }
  }
  await visit('generated')
  await visit('data')
  return createHash('sha256')
    .update(
      JSON.stringify({
        ...content,
        sources: content.sources.map(({ url, sha256 }) => ({ url, sha256 })),
        files,
      }),
    )
    .digest('hex')
}
